files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #f0f0f0;
  --muted: #a0a0b0;
  --border: #0f3460;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: 'Courier New', Courier, monospace;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.quiz-card {
  background: var(--card);
  border: 4px solid var(--border);
  border-radius: 0;
  padding: 32px 24px;
  max-width: 420px;
  width: 100%;
  text-align: center;
  box-shadow: 8px 8px 0 var(--border);
}

h1 {
  font-size: 28px;
  letter-spacing: 2px;
  margin-bottom: 24px;
  text-transform: uppercase;
  color: var(--accent);
}

.question {
  font-size: 24px;
  margin-bottom: 24px;
  min-height: 36px;
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.answer-btn,
.control-btn {
  font-family: inherit;
  font-size: 18px;
  padding: 12px 24px;
  border: 3px solid var(--border);
  background: var(--bg);
  color: var(--text);
  cursor: pointer;
  transition: background 0.1s, transform 0.1s;
  min-width: 80px;
}

.answer-btn:hover:not(:disabled),
.control-btn:hover:not(:disabled) {
  background: var(--accent);
}

.answer-btn:focus-visible,
.control-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.answer-btn:active:not(:disabled),
.control-btn:active:not(:disabled) {
  transform: translate(2px, 2px);
}

.answer-btn:disabled,
.control-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.score-line {
  font-size: 20px;
  margin-bottom: 24px;
}

#score {
  color: var(--accent);
  font-weight: bold;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

@media (max-width: 400px) {
  body { font-size: 16px; }
  .quiz-card { padding: 24px 16px; }
  h1 { font-size: 24px; }
  .question { font-size: 20px; }
  .answer-btn, .control-btn { padding: 10px 18px; font-size: 16px; }
}

const state = {
  currentQuestion: 0,
  score: 0,
  answered: false
};

const questions = [
  { text: '2 + 2 = ?', answers: ['4', '5'], correct: '4' },
  { text: '3 + 3 = ?', answers: ['5', '6'], correct: '6' }
];

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

function render() {
  if (state.currentQuestion < questions.length) {
    const q = questions[state.currentQuestion];
    questionEl.textContent = q.text;
    answerA.textContent = q.answers[0];
    answerB.textContent = q.answers[1];
    answerA.disabled = state.answered;
    answerB.disabled = state.answered;
    nextBtn.disabled = !state.answered;
  } else {
    questionEl.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
    nextBtn.disabled = true;
  }
  scoreEl.textContent = state.score;
}

function handleAnswer(selected) {
  if (state.answered || state.currentQuestion >= questions.length) return;
  const q = questions[state.currentQuestion];
  if (selected === q.correct) {
    state.score++;
  }
  state.answered = true;
  render();
}

function handleNext() {
  if (!state.answered) return;
  state.currentQuestion++;
  state.answered = false;
  render();
}

function handleRestart() {
  state.currentQuestion = 0;
  state.score = 0;
  state.answered = false;
  render();
}

answerA.addEventListener('click', () => handleAnswer(answerA.textContent));
answerB.addEventListener('click', () => handleAnswer(answerB.textContent));
nextBtn.addEventListener('click', handleNext);
restartBtn.addEventListener('click', handleRestart);

render();
